import data from "../../../pricing/aws.json" with { type: "json" }
import * as Pricing from "../Pricing.ts"

/**
 * AWS's prices, from the catalog in the repo (`pricing/aws.json`, generated by `tools/pricing/`). Decoded on first use,
 * so a design that never asks what it costs never pays for reading it.
 */
let catalog: Pricing.Catalog | undefined
export const prices = (): Pricing.Catalog => (catalog ??= Pricing.decode(data))
